import re, subprocess, sys, pathlib, glob
RE = re.compile(r'\*\*(?P<name>\w+)\*\* \((?P<ts>[^)]+)\)\n\nSource: (?P<br>friend/\w+) @ (?P<sha>[0-9a-f]{40})\n\n(?P<text>.*?)(?=\n\n\*\*\w+\*\* \(|\Z)', re.S)
def body(sha):
    out = subprocess.run(['git','-C','/tmp/shurik-workspace-yHQYP9','log','-1','--format=%cI%n%B',sha],capture_output=True,text=True).stdout
    ts, rest = out.split('\n',1)
    i = rest.find('Reply-To:')
    if i < 0: return ts.strip(), None
    j = rest.find('\n\n', i)
    return ts.strip(), rest[j+2:].strip()
bad = 0; total = 0; shas = {}
for path in sorted(glob.glob('S*/E*.md')):
    for m in RE.finditer(pathlib.Path(path).read_text()):
        total += 1
        sha = m.group('sha')
        if sha in shas:
            print(f'DUPLICATE {sha} in {path} and {shas[sha]}'); bad += 1
        shas[sha] = path
        ts, utter = body(sha)
        if utter is None:
            print(f'{path}: {sha} has no utterance block'); bad += 1; continue
        if m.group('text').strip() != utter:
            bad += 1
            print(f'MISMATCH {path} {sha}\n  file: {m.group("text").strip()!r}\n  src : {utter!r}')
        if m.group('ts') != ts:
            bad += 1; print(f'TIMESTAMP {path} {sha}: file {m.group("ts")} != src {ts}')
print(f'checked {total} entries, {bad} problems, {len(shas)} unique shas')
